#include "agent_client.h"
#include "syscall.h"
#include "text.h"
const char *agent_state_label(uint32_t state) { static const char *const labels[]={"Planning","Review","Approved","Running","Done","Cancelled","Failed"}; return state<=AGENT_FAILED ? labels[state] : "Unknown"; }
const char *agent_tool_label(uint32_t tool) { static const char *const names[]={"invalid","mkdir","write","read","list","move","delete","system"}; return tool>=AGENT_MKDIR && tool<=AGENT_SYSTEM ? names[tool] : names[0]; }
const char *agent_audit_label(uint32_t event) { static const char *const names[]={"Unknown","Plan submitted","Approved","Action completed","Done","Cancelled","Failed","Released","Started"}; return event<=8 ? names[event] : names[0]; }
const char *agent_error_label(long error) { if(error==0) { return "Ready"; } if(error==-22 || error==-7) { return "Unsupported, ambiguous or oversized request"; } if(error==-100 || error==-111) { return "Model bridge unavailable; check host bridge/network"; } if(error==-110) { return "Request timed out; review or retry sooner"; } if(error==-125) { return "Cancelled; completed actions remain"; } if(error==-1 || error==-13) { return "Permission or explicit consent required"; } if(error==-24 || error==-28) { return "Job, process or RAM storage limit reached"; } if(error==-11) { return "Finish or cancel the current job first"; } if(error==-3) { return "Job no longer exists"; } if(error==-71 || error==-5) { return "Invalid or incomplete model/tool response"; } if(error==-2) { return "File or directory does not exist"; } if(error==-17) { return "Destination already exists"; } return "Operation failed"; }
long agent_begin(const char *intent, uint32_t backend) { struct agent_request request={.backend=backend}; size_t length=text_length(intent); if(length==0 || length>=sizeof(request.intent)) { return -7; } text_copy(request.intent,intent,sizeof(request.intent)); return user_call(SYS_AGENT_START,(uintptr_t)&request,0,0); }
long agent_status(uint64_t id, struct agent_job_info *info) { return user_call(SYS_AGENT_STATUS,id,(uintptr_t)info,0); }
long agent_review(uint64_t id, struct agent_plan *plan) { return user_call(SYS_AGENT_REVIEW,id,(uintptr_t)plan,0); }
long agent_approve(uint64_t id, bool deletion) { return user_call(SYS_AGENT_APPROVE,id,AGENT_APPROVE_PLAN|(deletion ? AGENT_APPROVE_DELETE : 0u),0); }
long agent_cancel(uint64_t id) { return user_call(SYS_AGENT_CANCEL,id,0,0); }
long agent_release(uint64_t id) { long result; for(unsigned int i=0;i<20;++i) { result=user_call(SYS_AGENT_RELEASE,id,0,0); if(result!=SYS_EAGAIN) { return result; } (void)user_call(SYS_SLEEP,1,0,0); } return SYS_EAGAIN; }
long agent_wait(uint64_t id, bool review, struct agent_job_info *info) { for(unsigned int i=0;i<6100;++i) { long result=agent_status(id,info); if(result<0) { return result; } if(info->state>=AGENT_DONE || (review && info->state==AGENT_REVIEW)) { return 0; } (void)user_call(SYS_SLEEP,1,0,0); } return -110; }
static void out_number(void (*emit)(const char *), int64_t number) { char buffer[22]; (void)text_number(buffer,number); emit(buffer); }
static void quoted(void (*emit)(const char *), const char *value) { emit("\""); for(size_t i=0;value[i]!=0;++i) { char ch[2]={value[i],0}; if(value[i]=='\n') { emit("\\n"); } else if(value[i]=='\t') { emit("\\t"); } else { if(value[i]=='"' || value[i]=='\\') { emit("\\"); } emit(ch); } } emit("\""); }
static void summary(void (*emit)(const char *), const struct agent_job_info *info) { emit("job="); out_number(emit,(int64_t)info->id); emit(" "); emit(agent_state_label(info->state)); emit(" completed="); out_number(emit,info->completed); emit("/"); out_number(emit,info->total); if(info->error!=0) { emit(" error="); out_number(emit,info->error); emit(" "); emit(agent_error_label(info->error)); } emit("\n"); if(info->result[0]!=0) { emit(info->result); emit("\n"); } }
static long show_plan(uint64_t id, void (*emit)(const char *)) { struct agent_plan plan; long result=agent_review(id,&plan); if(result<0) { return result; } for(uint32_t i=0;i<plan.count;++i) { const struct agent_action *action=&plan.actions[i]; out_number(emit,i+1u); emit(". "); emit(agent_tool_label(action->tool)); if(action->path[0]!=0) { emit(" "); quoted(emit,action->path); } if(action->other[0]!=0) { emit(" -> "); quoted(emit,action->other); } if(action->tool==AGENT_WRITE) { emit(" text="); quoted(emit,action->text); } emit("\n"); } emit("Review above; approve explicitly. Deletion also needs 'delete'.\n"); return 0; }
long agent_command(int count, char **args, void (*emit)(const char *text)) {
    if(count<2) { emit("agent plan|model 'intent'; review|approve|cancel|status|audit|release ID; jobs\n"); return 0; }
    const char *verb=args[1]; struct agent_job_info info;
    if(text_equal(verb,"plan") || text_equal(verb,"model")) { if(count!=3) { return -22; } long id=agent_begin(args[2],text_equal(verb,"model") ? AGENT_BACKEND_MODEL : AGENT_BACKEND_OFFLINE); if(id<0) { emit(agent_error_label(id)); emit("\n"); return id; } long result=agent_wait((uint64_t)id,true,&info); if(result<0) { return result; } summary(emit,&info); return info.state==AGENT_REVIEW ? show_plan((uint64_t)id,emit) : info.error; }
    if(text_equal(verb,"jobs")) { if(count!=2) { return -22; } unsigned int found=0; for(uint64_t slot=0;slot<AGENT_JOB_MAX;++slot) { long result=user_call(SYS_AGENT_STATUS,0,(uintptr_t)&info,slot); if(result<0) { return result; } if(result==1) { summary(emit,&info); ++found; } } if(found==0) { emit("No active agent jobs\n"); } return 0; }
    uint64_t id; if(count<3 || count>4 || !text_unsigned(args[2],&id) || id==0) { return -22; }
    if(text_equal(verb,"approve")) { if(count==4 && !text_equal(args[3],"delete")) { return -22; } long result=agent_approve(id,count==4); if(result<0) { return result; } result=agent_wait(id,false,&info); if(result<0) { return result; } summary(emit,&info); return info.error; }
    if(count!=3) { return -22; }
    if(text_equal(verb,"cancel")) { long result=agent_cancel(id); if(result<0) { return result; } }
    else if(text_equal(verb,"release")) { return agent_release(id); }
    else if(text_equal(verb,"audit")) { struct agent_audit event; uint64_t cursor=0; for(unsigned int i=0;i<AGENT_AUDIT_MAX;++i) { long result=user_call(SYS_AGENT_AUDIT,id,(uintptr_t)&event,cursor); if(result<=0) { return result; } cursor=event.sequence; emit("audit sequence="); out_number(emit,(int64_t)cursor); emit(" event="); out_number(emit,event.event); emit(" tool="); emit(agent_tool_label(event.tool)); if(event.path[0]!=0) { emit(" path="); quoted(emit,event.path); } if(event.other[0]!=0) { emit(" to="); quoted(emit,event.other); } emit(" status="); out_number(emit,event.status); emit("\n"); } return 0; }
    else if(!text_equal(verb,"status") && !text_equal(verb,"review")) { return -22; }
    long result=agent_status(id,&info); if(result<0) { return result; } summary(emit,&info); return text_equal(verb,"review") ? show_plan(id,emit) : 0;
}
